import{_ as a,q as s,z as n,V as p}from"./chunks/framework.OtifAeFI.js";const e=JSON.parse('{"title":"Cloudfalre 优选IP","description":"CF优选IP教程","frontmatter":{"title":"Cloudfalre 优选IP","tags":["Cloudfalre"],"categories":["Cloudfalre"],"date":"2025-01-01T00:00:00.000Z","description":"CF优选IP教程","articleGPT":"由于GFW干扰，Cloudflare CDN在中国大陆访问不佳。通过Cloudflare的Anycast技术，可以筛选出在中国大陆访问友好的IP，即“CF优选”。需要两个域名，其中一个托管在Cloudflare，并开通Saas。通过设置辅助域名和回退源，将目标域名指向加速域名（例如ip.sb）。加速域名指向优选IP，从而实现加速访问。文章还提供了一些可替换的加速域名列表，方便用户选择。","references":[{"title":"【视频教程】双域名白嫖Cloudflare优选IP，最优CDN给自己网站加速，尽情享受CF免费服务","url":"https://linux.do/t/topic/127255"}],"head":[["link",{"rel":"canonical","href":"https://www.696898.xyz/posts/2025/0101"}]]},"headers":[],"relativePath":"posts/2025/0101.md","filePath":"posts/2025/0101.md","lastUpdated":1741095097000}');const l=a({name:"posts/2025/0101.md"},[["render",function(a,e,l,c,i,r){return n(),s("div",null,e[0]||(e[0]=[p('<h1 id="cloudflare-优选-ip" tabindex="-1">Cloudflare 优选 IP <a class="header-anchor" href="#cloudflare-优选-ip" aria-label="Permalink to &quot;Cloudflare 优选 IP&quot;">​</a></h1><p>由于 GFW 的原因，Cloudflare 的 CDN 在中国大陆访问性不佳。但是，由于 Cloudflare 使用了 Anycast（任播）技术，我们可以筛选出其中在中国大陆访问相对友好的 IP 用于我们的 CDN 节点，这就是所谓的 CF 优选。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ol><li>需要拥有两个域名，最少一个托管在 Cloudflare。</li><li>需要绑定付款方式以开通 SaaS (需要 Visa、Mastercard、PayPal)。</li></ol><h2 id="开通-saas" tabindex="-1">开通 SaaS <a class="header-anchor" href="#开通-saas" aria-label="Permalink to &quot;开通 SaaS&quot;">​</a></h2><p><a class="img-fancybox" href="https://pic1.imgdb.cn/item/67763a1bd0e0a243d4edc478.png" data-fancybox="gallery" data-caption="SaaS"><img class="post-img" src="https://pic1.imgdb.cn/item/67763a1bd0e0a243d4edc478.png" alt="SaaS" loading="lazy"><span class="post-img-tip">SaaS</span></a></p><p>如上图所示，在任意域名处开通自定义主机名，需要绑定外币信用卡或 Paypal（支持银联）。</p><h2 id="配置辅助域名" tabindex="-1">配置辅助域名 <a class="header-anchor" href="#配置辅助域名" aria-label="Permalink to &quot;配置辅助域名&quot;">​</a></h2><p>假设：</p><ul><li><code>A.com</code> 为你想访问的域名 (不要求托管在 CF)。</li><li><code>B.com</code> 为辅助域名 (要求托管在 CF)。</li></ul><h3 id="添加解析" tabindex="-1">添加解析 <a class="header-anchor" href="#添加解析" aria-label="Permalink to &quot;添加解析&quot;">​</a></h3><p><a class="img-fancybox" href="https://pic1.imgdb.cn/item/677649aed0e0a243d4edc9bf.png" data-fancybox="gallery" data-caption="添加DNS记录"><img class="post-img" src="https://pic1.imgdb.cn/item/677649aed0e0a243d4edc9bf.png" alt="添加DNS记录" loading="lazy"><span class="post-img-tip">添加DNS记录</span></a></p><p>这里以 <code>origin.b.com</code> 为例，添加一条解析类型为 <code>A</code> 的解析记录，IPv4 地址填写你的源站。</p><p><strong>注意：</strong> 一定要开启小黄云让 CF 代理流量。</p><p><em><strong>TIPS:</strong></em> 或者添加一条 <code>CNAME</code> 解析记录，主机名填写源站域名。</p><h3 id="添加回退源" tabindex="-1">添加回退源 <a class="header-anchor" href="#添加回退源" aria-label="Permalink to &quot;添加回退源&quot;">​</a></h3><p>我们在 <code>B.com</code> 处添加一个自定义回退源，这里以 <code>origin.b.com</code> 为例。</p><p><a class="img-fancybox" href="https://pic1.imgdb.cn/item/67764663d0e0a243d4edc85f.png" data-fancybox="gallery" data-caption="添加回退源"><img class="post-img" src="https://pic1.imgdb.cn/item/67764663d0e0a243d4edc85f.png" alt="添加回退源" loading="lazy"><span class="post-img-tip">添加回退源</span></a></p><h3 id="添加自定义主机名" tabindex="-1">添加自定义主机名 <a class="header-anchor" href="#添加自定义主机名" aria-label="Permalink to &quot;添加自定义主机名&quot;">​</a></h3><p><a class="img-fancybox" href="https://pic1.imgdb.cn/item/67764c82d0e0a243d4edcc04.png" data-fancybox="gallery" data-caption="添加自定义主机名"><img class="post-img" src="https://pic1.imgdb.cn/item/67764c82d0e0a243d4edcc04.png" alt="添加自定义主机名" loading="lazy"><span class="post-img-tip">添加自定义主机名</span></a></p><p><a class="img-fancybox" href="https://pic1.imgdb.cn/item/67764cd2d0e0a243d4edcc26.png" data-fancybox="gallery" data-caption="添加自定义主机名"><img class="post-img" src="https://pic1.imgdb.cn/item/67764cd2d0e0a243d4edcc26.png" alt="添加自定义主机名" loading="lazy"><span class="post-img-tip">添加自定义主机名</span></a></p><p>将你想访问的域名 <code>blog.a.com</code> 添加为自定义主机名。</p><p><a class="img-fancybox" href="https://pic1.imgdb.cn/item/67764d07d0e0a243d4edcc40.png" data-fancybox="gallery" data-caption="验证TXT"><img class="post-img" src="https://pic1.imgdb.cn/item/67764d07d0e0a243d4edcc40.png" alt="验证TXT" loading="lazy"><span class="post-img-tip">验证TXT</span></a></p><p>随即在主域名 <code>A.com</code> 添加两条 <code>TXT</code> 类型的记录，用于 SSL 证书申请。</p><h2 id="配置加速域名" tabindex="-1">配置加速域名 <a class="header-anchor" href="#配置加速域名" aria-label="Permalink to &quot;配置加速域名&quot;">​</a></h2><p>我们可以通过本地测速或者拨测的方式进行筛选出你需要的 IP，这里不再赘述，有需要的可以自行搭建。</p><p>这里我们建议使用他人筛选出的域名，我们以加速域名 <code>ip.sb</code> 为例。</p><p>在 <code>blog.a.com</code> 添加一个 <code>CNAME</code> 解析记录，主机名为 <code>ip.sb</code>（可能不会长期维护）。</p><p>这样 CF 优选 IP 就配置完成了。</p><h2 id="加速域名" tabindex="-1">加速域名 <a class="header-anchor" href="#加速域名" aria-label="Permalink to &quot;加速域名&quot;">​</a></h2><p>这里提供一些大佬长期维护或者企业使用的域名，可以将 <code>ip.sb</code> 替换为以下域名。</p><details class="details custom-block"><summary>点击展开</summary><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span># 本人维护的加速域名</span></span>\n<span class="line"><span>cfdns.koishi.news</span></span>\n<span class="line"><span># 其他渠道搜集域名</span></span>\n<span class="line"><span>time.cloudflare.com</span></span>\n<span class="line"><span>shopify.com</span></span>\n<span class="line"><span>time.is</span></span>\n<span class="line"><span>icook.hk</span></span>\n<span class="line"><span>icook.tw</span></span>\n<span class="line"><span>ip.sb</span></span>\n<span class="line"><span>japan.com</span></span>\n<span class="line"><span>malaysia.com</span></span>\n<span class="line"><span>russia.com</span></span>\n<span class="line"><span>singapore.com</span></span>\n<span class="line"><span>skk.moe</span></span>\n<span class="line"><span>www.visa.com</span></span>\n<span class="line"><span>www.visa.com.sg</span></span>\n<span class="line"><span>www.visa.com.hk</span></span>\n<span class="line"><span>www.visa.com.tw</span></span>\n<span class="line"><span>www.visa.co.jp</span></span>\n<span class="line"><span>www.visakorea.com</span></span>\n<span class="line"><span>www.gco.gov.qa</span></span>\n<span class="line"><span>www.gov.se</span></span>\n<span class="line"><span>www.gov.ua</span></span>\n<span class="line"><span>www.digitalocean.com</span></span>\n<span class="line"><span>www.csgo.com</span></span>\n<span class="line"><span>www.shopify.com</span></span>\n<span class="line"><span>www.whoer.net</span></span>\n<span class="line"><span>www.whatismyip.com</span></span>\n<span class="line"><span>www.ipget.net</span></span>\n<span class="line"><span>www.hugedomains.com</span></span>\n<span class="line"><span>www.udacity.com</span></span>\n<span class="line"><span>www.4chan.org</span></span>\n<span class="line"><span>www.okcupid.com</span></span>\n<span class="line"><span>www.glassdoor.com</span></span>\n<span class="line"><span>www.udemy.com</span></span>\n<span class="line"><span>www.baipiao.eu.org</span></span>\n<span class="line"><span>alejandracaiccedo.com</span></span>\n<span class="line"><span>log.bpminecraft.com</span></span>\n<span class="line"><span>www.boba88slot.com</span></span>\n<span class="line"><span>gur.gov.ua</span></span>\n<span class="line"><span>www.zsu.gov.ua</span></span>\n<span class="line"><span>www.iakeys.com</span></span>\n<span class="line"><span>edtunnel-dgp.pages.dev</span></span>\n<span class="line"><span>www.d-555.com</span></span>\n<span class="line"><span>fbi.gov</span></span>\n<span class="line"><span>www.sean-now.com</span></span>\n<span class="line"><span>download.yunzhongzhuan.com</span></span>\n<span class="line"><span>whatismyipaddress.com</span></span>\n<span class="line"><span>www.ipaddress.my</span></span>\n<span class="line"><span>www.pcmag.com</span></span>\n<span class="line"><span>www.ipchicken.com</span></span>\n<span class="line"><span>www.iplocation.net</span></span>\n<span class="line"><span>iplocation.io</span></span>\n<span class="line"><span>www.who.int</span></span>\n<span class="line"><span>www.wto.org</span></span>\n<span class="line"><span>#其他选择，都是官方 IP 优选</span></span>\n<span class="line"><span>jp.byun.eu.org</span></span>\n<span class="line"><span>un.goasa.top</span></span>\n<span class="line"><span>emby2.misakaf.org</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br></div></div></details>',32)]))}]]);export{e as __pageData,l as default};
